00050 //
00051 // Abstract interface for reading RLE symbols for surface.
00052 //
00053 class SymbolSource {
00054 public:
00055     virtual ~SymbolSource(){};
00056     virtual void start() = 0;
00057     virtual unsigned get(unsigned state) = 0;
00058     virtual unsigned get_byte() = 0;
00059 };
00060 
00061 // SymbolSourceConstant
00062 //
00063 // Always return a constant
00064 //
00065 class SymbolSourceConstant : public SymbolSource {
00066 public:
00067     SymbolSourceConstant(unsigned c) : c_(c) {}
00068 
00069     void start() override {}
00070 
00071     unsigned get(unsigned state) override { return c_; }
00072 
00073     unsigned get_byte() override { return c_; }
00074 
00075 private:
00076     const unsigned c_;
00077 };
00078 
00079 // SymbolSourceRaw
00080 //
00081 // Treats source data as raw symbols with no coding
00082 //
00083 class SymbolSourceRaw : public SymbolSource {
00084 public:
00085     SymbolSourceRaw(BitstreamUnpacker &b) : b_(b) {}
00086 
00087     void start() override {}
00088 
00089     unsigned get(unsigned state) override { return b_.byte(); }
00090 
00091     unsigned get_byte() override { return b_.byte(); }
00092 
00093 private:
00094     BitstreamUnpacker &b_;
00095 };
00096 
00097 // SymbolSourceHuffman
00098 //
00099 // Source is huffman coded data, using different trees for each part of the RLE coding.
00100 //
00101 class SymbolSourceHuffman : public SymbolSource {
00102 public:
00103     SymbolSourceHuffman(unsigned num_states, BitstreamUnpacker &b) : states_(num_states), b_(b) {}
00104 
00105     void start() override {
00106         for (unsigned i = 0; i < states_.size(); ++i) {
00107             states_[i].read_codes(b_);
00108         }
00109     }
00110 
00111     unsigned get(unsigned state) override {
00112         assert(state < states_.size());
00113         return states_[state].decode_symbol(b_);
00114     }
00115 
00116     unsigned get_byte() override { return b_.u(8, "first_symbol"); }
00117 
00118 private:
00119     std::vector<HuffmanDecoder> states_;
00120     BitstreamUnpacker &b_;
00121 };
00122 
00123 // Create symbol source for given encoded data
00124 //
00125 static std::unique_ptr<SymbolSource> create_symbol_source(unsigned num_states, bool entropy_enabled, bool rle_only,
00126                                                           BitstreamUnpacker &b, unsigned constant) {
00127     if (entropy_enabled) {
00128         if (rle_only)
00129             return std::unique_ptr<SymbolSource>(new SymbolSourceRaw(b));
00130         else
00131             return std::unique_ptr<SymbolSource>(new SymbolSourceHuffman(num_states, b));
00132     } else {
00133         return std::unique_ptr<SymbolSource>(new SymbolSourceConstant(constant));
00134     }
00135 }
00136 
00138 //
00139 // Run Length coded residuals
00140 //
00141 EntropyDecoderResidualsBase::rle_pel_t EntropyDecoderResidualsBase::decode_pel(SymbolSource &source) const {
00142     rle_pel_t r = {0, 0};
00143 
00144     unsigned symbol = source.get(STATE_LSB);
00145 
00146     // If bit 0 is set, an MS byte follows
00147     if (symbol & 0x01) {
00148         unsigned lsb_symbol = symbol;
00149         symbol = source.get(STATE_MSB);
00150         r.pel = ((((symbol & 0x7f) << 8) | (lsb_symbol & 0xfe)) >> 1) - 0x2000;
00151     } else {
00152         r.pel = ((symbol & 0x7e) - 0x40) >> 1;
00153     }
00154 
00155     // if the bit 7 is set, zero run count follows
00156     if (symbol & 0x80) {
00157         // LSByte first
00158         /***
00159         unsigned bit_offset = 0;
00160         do {
00161             symbol = source.get(STATE_ZERO);
00162             r.zero_runlength |= (symbol & 0x7f) << bit_offset;
00163             bit_offset += 7;
00164         } while (symbol & 0x80);
00165         ***/
00166         // MSByte first
00167         /***/
00168         r.zero_runlength = 0;
00169         do {
00170             symbol = source.get(STATE_ZERO);
00171             r.zero_runlength = (r.zero_runlength << 7) | (symbol & 0x7f);
00172         } while (symbol & 0x80);
00173         /***/
00174     }
00175 
00176     return r;
00177 }
00178 
00179 // Decoding full frame raster order
00180 Surface EntropyDecoderResiduals::process(unsigned width, unsigned height, bool entropy_enabled, bool rle_only,
00181                                          BitstreamUnpacker &b) {
00182     // Set up source of symbols - empty layers are have a constant value of 0x40
00183     const auto symbol_source(create_symbol_source(STATE_COUNT, entropy_enabled, rle_only, b, 0x40));
00184 
00185     // Make the new surface
00186     auto dest = Surface::build_from<int16_t>();
00187     dest.reserve(width, height);
00188 
00189     // Current PEL/run value
00190     rle_pel_t current = {0, 0};
00191 
00192     // Read any huffman tables
00193     symbol_source->start();
00194 
00195     for (unsigned y = 0; y < height; ++y) {
00196         int16_t *__restrict pdst = dest.data(0, y);
00197         for (unsigned x = 0; x < width; ++x) {
00198             if (current.zero_runlength > 0) {
00199                 // Extend the run of zeros
00200                 // dest.write(x, y, 0);
00201                 *pdst++ = 0;
00202                 --current.zero_runlength;
00203             } else {
00204                 // Write PEL value
00205                 current = decode_pel(*symbol_source);
00206                 // dest.write(x, y, current.pel);
00207                 *pdst++ = current.pel;
00208             }
00209         }
00210     }
00211 
00212     return dest.finish();
00213 }
00214 
00215 // Decoding in coding unit order
00216 Surface EntropyDecoderResidualsTiled::process(unsigned width, unsigned height, bool entropy_enabled, bool rle_only,
00217                                               BitstreamUnpacker &b, unsigned transform_block_size) {
00218     // Set up source of symbols - empty layers are have a constant value of 0x40
00219     const auto symbol_source(create_symbol_source(STATE_COUNT, entropy_enabled, rle_only, b, 0x40));
00220 
00221     // Make the new surface
00222     auto dest = Surface::build_from<int16_t>();
00223     dest.reserve(width, height);
00224 
00225     // Divisor for block->tiles
00226     const unsigned d = 32 / transform_block_size;
00227 
00228     // Current PEL/run value
00229     rle_pel_t current = {0, 0};
00230 
00231     // Read any huffman tables
00232     symbol_source->start();
00233 
00234     for (unsigned ty = 0; ty < height; ty += d) {
00235         for (unsigned tx = 0; tx < width; tx += d) {
00236 
00237             // For each transform in tile
00238             // for (unsigned y = ty; y < std::min(ty + d, height); ++y) {
00239             for (unsigned y = ty; y < LCEVC_MIN(ty + d, height); ++y) {
00240                 //              int16_t *__restrict pdst = dest.data(tx, y);
00241                 // for (unsigned x = tx; x < std::min(tx + d, width); ++x) {
00242                 for (unsigned x = tx; x < LCEVC_MIN(tx + d, width); ++x) {
00243                     if (current.zero_runlength > 0) {
00244                         // Extend the run of zeros
00245                         dest.write(x, y, 0);
00246                         //                      *pdst++ = 0;
00247                         --current.zero_runlength;
00248                     } else {
00249                         // Write PEL value
00250                         current = decode_pel(*symbol_source);
00251                         dest.write(x, y, current.pel);
00252                         //                      *pdst++ = current.pel;
00253                     }
00254                 }
00255             }
00256         }
00257     }
00258 
00259     return dest.finish();
00260 }
