00263 //
00264 // Run Length coded temporal bits
00265 //
00266 unsigned EntropyDecoderTemporal::decode_run(SymbolSource &source, bool symbol) const {
00267     unsigned count = 0;
00268     unsigned c = 0;
00269     do {
00270         c = source.get(symbol ? STATE_ONE_RUN : STATE_ZERO_RUN);
00271         count = (count << 7) | (c & 0x7f);
00272     } while (c & 0x80);
00273 
00274     return count;
00275 }
00276 
00277 Surface EntropyDecoderTemporal::process(unsigned width, unsigned height, bool entropy_enabled, bool rle_only, BitstreamUnpacker &b,
00278                                         unsigned transform_block_size, bool use_reduced_signalling) {
00279     const auto symbol_source(create_symbol_source(STATE_COUNT, entropy_enabled, rle_only, b, 0));
00280 
00281     // Make the new surface
00282     auto dest = Surface::build_from<uint8_t>();
00283     dest.reserve(width, height);
00284 
00285     if (!entropy_enabled)
00286         return dest.fill(TemporalType::TEMPORAL_PRED, width, height).finish();
00287 
00288     // Divisor for block->tiles
00289     const unsigned d = 32 / transform_block_size;
00290 
00291     // Read any huffman tables
00292     symbol_source->start();
00293 
00294     // Get the first symbol & count
00295     bool symbol = (symbol_source->get_byte() != 0);
00296 
00297     unsigned count = decode_run(*symbol_source, symbol);
00298 
00299     // For each tile ..
00300     for (unsigned ty = 0; ty < height; ty += d) {
00301         for (unsigned tx = 0; tx < width; tx += d) {
00302 
00303             bool intra_tile = false;
00304             // For each transform in tile
00305             // for (unsigned y = ty; y < std::min(ty + d, height); ++y) {
00306             for (unsigned y = ty; y < LCEVC_MIN(ty + d, height); ++y) {
00307                 uint8_t *__restrict pdst = dest.data(tx, y);
00308                 // for (unsigned x = tx; x < std::min(tx + d, width); ++x) {
00309                 for (unsigned x = tx; x < LCEVC_MIN(tx + d, width); ++x) {
00310                     if (use_reduced_signalling && intra_tile) {
00311                         // The whole tile was flagged as intra
00312                         *pdst++ = TemporalType::TEMPORAL_INTR;
00313                     } else {
00314                         // Get next symbol
00315                         while (count == 0) {
00316                             // Flip symbol and get next count
00317                             symbol = !symbol;
00318                             count = decode_run(*symbol_source, symbol);
00319                         }
00320 
00321                         // Check for intra tile
00322                         if (use_reduced_signalling && symbol && tx == x && ty == y)
00323                             intra_tile = true;
00324 
00325                         // Write to dst
00326                         // dest.write(x, y, symbol ? TemporalType::TEMPORAL_INTR : TemporalType::TEMPORAL_PRED);
00327                         *pdst++ = (symbol ? TemporalType::TEMPORAL_INTR : TemporalType::TEMPORAL_PRED);
00328 
00329                         count--;
00330                     }
00331                 }
00332             }
00333         }
00334     }
00335 
00336     return dest.finish();
00337 }
