00340 //
00341 // Run Length coded temporal bits
00342 //
00343 unsigned EntropyDecoderFlags::decode_run(SymbolSource &source, bool symbol) const {
00344     unsigned count = 0;
00345     unsigned c = 0;
00346     do {
00347         c = source.get(symbol ? STATE_ONE_RUN : STATE_ZERO_RUN);
00348         count = (count << 7) | (c & 0x7f);
00349     } while (c & 0x80);
00350 
00351     return count;
00352 }
00353 
00354 Surface EntropyDecoderFlags::process(unsigned width, unsigned height, BitstreamUnpacker &b) {
00355     const auto symbol_source(create_symbol_source(STATE_COUNT, true, true, b, 0));
00356 
00357     // Make the new surface
00358     auto dest = Surface::build_from<uint8_t>();
00359     dest.reserve(width, height);
00360 
00361     // Read any huffman tables
00362     symbol_source->start();
00363 
00364     // Get the first symbol & count
00365     bool symbol = (symbol_source->get_byte() != 0);
00366 
00367     unsigned count = decode_run(*symbol_source, symbol);
00368 
00369     // For each tile ..
00370     for (unsigned y = 0; y < height; ++y) {
00371         uint8_t *__restrict pdst = dest.data(0, y);
00372         for (unsigned x = 0; x < width; ++x) {
00373             bool intra_tile = false;
00374             // Get next symbol
00375             while (count == 0) {
00376                 // Flip symbol and get next count
00377                 symbol = !symbol;
00378                 count = decode_run(*symbol_source, symbol);
00379             }
00380             // Write to dst
00381             // dest.write(x, y, symbol ? 0xff : 0x00);
00382             *pdst++ = (symbol ? 0xff : 0x00);
00383             count--;
00384         }
00385     }
00386 
00387     return dest.finish();
00388 }
