00391 //
00392 // Coded sizes
00393 //
00394 uint16_t EntropyDecoderSizes::decode_size(SymbolSource &source) const {
00395 
00396     const unsigned l = source.get(STATE_LSB);
00397 
00398     // If bit 0 is set, an MS byte follows
00399     if (l & 0x01) {
00400         const unsigned m = source.get(STATE_MSB);
00401         return (l >> 1) + (m << 7);
00402     } else {
00403         return l >> 1;
00404     }
00405 }
00406 
00407 int16_t EntropyDecoderSizes::decode_size_delta(SymbolSource &source) const {
00408 
00409     const unsigned l = source.get(STATE_LSB);
00410 
00411     // If bit 0 is set, an MS byte follows
00412     //
00413     // Sign extend from high bit of decoded value to recover signed delta
00414     //
00415     if (l & 0x01) {
00416         const unsigned m = source.get(STATE_MSB);
00417         const int16_t r = (l >> 1) + (m << 7);
00418         return r | ((r & 0x4000) << 1);
00419     } else {
00420         const uint8_t r = l >> 1;
00421         return (int8_t)(r | ((r & 0x40) << 1));
00422     }
00423 }
00424 
00425 Surface EntropyDecoderSizes::process(unsigned width, unsigned height, BitstreamUnpacker &b, const std::vector<bool> entropy_enabled,
00426                                      const unsigned tile_idx, CompressionType compression_type) {
00427     // Set up source of symbols
00428     const auto symbol_source(create_symbol_source(STATE_COUNT, true, false, b, 0));
00429 
00430     // Make the new surface
00431     auto dest = Surface::build_from<uint16_t>();
00432     dest.reserve(width, height);
00433 
00434     // Read any huffman tables
00435     symbol_source->start();
00436 
00437     if (compression_type == CompressionType_Prefix) {
00438         for (unsigned y = 0; y < height; ++y) {
00439             uint16_t *__restrict pdst = dest.data(0, y);
00440             for (unsigned x = 0; x < width; ++x) {
00441                 if (entropy_enabled[tile_idx + x])
00442                     *pdst++ = decode_size(*symbol_source);
00443                 else
00444                     *pdst++ = 0;
00445             }
00446         }
00447     } else if (compression_type == CompressionType_Prefix_OnDiff) {
00448         uint16_t p = 0;
00449         for (unsigned y = 0; y < height; ++y) {
00450             uint16_t *__restrict pdst = dest.data(0, y);
00451             for (unsigned x = 0; x < width; ++x) {
00452                 if (entropy_enabled[tile_idx + x]) {
00453                     const int diff = decode_size_delta(*symbol_source);
00454                     p += diff;
00455                     *pdst++ = p;
00456                 } else {
00457                     *pdst++ = 0;
00458                 }
00459             }
00460         }
00461     }
00462 
00463     return dest.finish();
00464 }
